```javascript
const canvas = document.getElementById('solarSystemCanvas');
const ctx = canvas.getContext('2d');

// Set canvas size to match window size
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;

function drawPlanet(x, y, radius, color) {
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, Math.PI * 2);
    ctx.fillStyle = color;
    ctx.fill();
    ctx.closePath();
}

function animate() {
    // Clear the canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw the sun at the center
    drawPlanet(canvas.width / 2, canvas.height / 2, 50, 'yellow');

    // Example planet orbit
    const planetRadius = 10; // Planet size
    const orbitRadius = 200; // Distance from the sun
    const angle = Date.now() / 1000; // Time-based angle for animation

    const x = canvas.width / 2 + orbitRadius * Math.cos(angle);
    const y = canvas.height / 2 + orbitRadius * Math.sin(angle);

    drawPlanet(x, y, planetRadius, 'blue');

    requestAnimationFrame(animate);
}

animate();
```

