     Shader "Custom/DotShader"
     {
         SubShader
         {
             Tags { "RenderType"="Opaque" }
             LOD 200

             Pass
             {
                 CGPROGRAM
                 #pragma vertex vert
                 #pragma fragment frag

                 struct appdata
                 {
                     float4 vertex : POSITION;
                     float2 uv : TEXCOORD0;
                 };

                 struct v2f
                 {
                     float2 uv : TEXCOORD0;
                     float4 vertex : SV_POSITION;
                 };

                 sampler2D _MainTex;
                 float4 _Color;

                 v2f vert (appdata v)
                 {
                     v2f o;
                     o.vertex = UnityObjectToClipPos(v.vertex);
                     o.uv = v.uv;
                     return o;
                 }

                 fixed4 frag (v2f i) : SV_Target
                 {
                     fixed4 col = tex2D(_MainTex, i.uv);
                     col.a *= _Color.a;
                     return col;
                 }
                 ENDCG
             }
